def check_permutation(m):
    divs = get_divisors(m)
    # The set of divisors is D.
    # We need a permutation a_1, ..., a_n of D such that each partial sum is a square.
    # One of the a_i is m. Since m is the largest, it must be the last one.
    # So a_n = m and S_n = sigma(m) = k^2.
    # S_{n-1} = sigma(m) - m = S_prop = r^2.
    # We need a permutation of the proper divisors D' = D \ {m} such that
    # each partial sum is a square.

    s_m = sigma(m)
    root_m = int(math.isqrt(s_m))
    if root_m * root_m != s_m:
        return False

    s_prop = s_m - m
    root_prop = int(math.isqrt(s_prop))
    if root_prop * root_prop != s_prop:
        return False

    d_prime = divs[:-1]

    def backtrack(remaining_divs, current_sum):
        if not remaining_divs:
            return True

        max_d = remaining_divs[-1]
        min_d = remaining_divs[0]

        start_k = int(math.isqrt(current_sum)) + 1
        for k in range(start_k, int(math.isqrt(current_sum + max_d)) + 1):
            sq = k * k
            d = sq - current_sum
            if d < min_d:
                continue
            idx = bisect.bisect_left(remaining_divs, d)
            if idx < len(remaining_divs) and remaining_divs[idx] == d:
                if backtrack(remaining_divs[:idx] + remaining_divs[idx+1:], sq):
                    return True
        return False

    # The first term a_1 must be a square divisor in d_prime.
    for i in range(len(d_prime)):
        d = d_prime[i]
        r = int(math.isqrt(d))
        if r * r == d:
            if backtrack(d_prime[:i] + d_prime[i+1:], d):
                return True
    return False

